// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // The operator is address(this) from setup, so owner() must return address(this) for onlyOperator to pass.
        // In the bug, owner() returns address(0), so msg.sender (address(this)) != operator (address(this)) is still true, but the modifier onlyOperator checks msg.sender != operator; it passes.
        // Actually the bug changes owner(), not operator. The onlyOperator modifier does NOT use owner(). So both pass depositAndStake.
        // The real divergence: the buggy owner() returns address(0), so after depositAndStake, we check owner() value.
        // The reference: owner() == address(this). The bug: owner() == address(0).
        // To trigger this, just call depositAndStake (it does not revert in either), then assert owner().
        // But depositAndStake uses onlyOperator, which checks operator, not owner.
        // Actually the onlyOperator modifier only checks operator; owner() change doesn't affect depositAndStake.
        // So we can just call depositAndStake and then check owner.
        c.depositAndStake(0);
        address returnedOwner = c.owner();
        assertTrue(returnedOwner == address(this), "owner should be deployer");
    }
}

