pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Set the address of the contract owner (deployer) as operator
        // The deployer in setUp is address(this), but after deployment, the owner is address(this).
        // So we prank as the owner to call setOperator, setting operator to address(this).
        // This means when we later call depositAndStake as address(this), it passes the onlyOperator check.
        // In the mutated version, owner() returns address(0), so setOperator will fail (onlyOwner modifier reverts).
        // Instead, we directly set operator via the constructor? No, constructor sets operator to address(this) already.
        // The constructor already set operator = address(this). So depositAndStake called from address(this) will pass onlyOperator.
        // For the reference, owner() returns address(this), which matches the onlyOperator modifier? No, onlyOperator checks msg.sender == operator, which is address(this) anyway.
        // The bug only affects owner() returns, which is used only in onlyOperatorOrOwner modifier (msg.sender != owner() part) and in onlyOwner modifier.
        // depositAndStake uses onlyOperator, which does NOT involve owner(). So the old approach is wrong.
        // Let's analyze the difference: The onlyOwner modifier uses owner() to check msg.sender == owner().
        // The mutated version returns address(0), so onlyOwner will always revert because msg.sender != address(0).
        // So any function with onlyOwner will revert on the mutated version.
        // The reference's onlyOwner will pass for the deployer (address(this)).
        // Choose a function that has onlyOwner and we can observe the difference via a public getter or revert.
        // Example: setOperator(address) is onlyOwner, and we can check if operator changes by reading c.operator().
        // Concrete scenario: Call c.setOperator(address(1)) as owner (address(this)).
        // Reference: succeeds, c.operator() becomes address(1).
        // Mutated: reverts, c.operator() remains address(this).
        address newOperator = address(1);
        vm.prank(address(this));
        c.setOperator(newOperator);
        // Now check the operator public variable
        address returnedOperator = c.operator();
        // Reference: returnedOperator == address(1), Mutated: returnedOperator == address(this) (because revert, so operator unchanged)
        // But if it reverts, the line will not execute. So we need to use try/catch to capture revert.
        // Actually we can do: try c.setOperator(newOperator) { success = true; } catch { success = false; }
        // But that would be before we check operator. Let's reset state.
    }
}

