pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // Set the caller as operator
        vm.prank(address(this));
        c.setOperator(address(this));

        // Provide some balance to the contract for the deposit
        vm.deal(address(this), 1000);

        // Call depositAndStake with a concrete amount
        vm.prank(address(this));
        c.depositAndStake(100);

        // The staked balance should be >0 in reference, 0 in mutant
        assertTrue(c.stakedBalance() > 0);
    }
}

