pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testRegression_property() public {
        // operator is address(this)
        bool success;
        try c.depositAndStake(100) {
            success = true;
        } catch {
            success = false;
        }
        // In reference (correct): booster.deposit on address(0) reverts -> success == false
        // In mutant: deposit is skipped -> success == true
        // We want the test to PASS on reference (false) and FAIL on mutant (true)
        assertTrue(!success);
    }
}

